inicial.estilo.css:
/* 1. body: a pilha Verdana, Tahoma, sans-serif */

/* 2. h1: a pilha Georgia, "Times New Roman", serif */

/* 3. code: a pilha "Courier New", monospace */

solucao.estilo.css:
body {
  font-family: Verdana, Tahoma, sans-serif;
}

h1 {
  font-family: Georgia, "Times New Roman", serif;
}

code {
  font-family: "Courier New", monospace;
}

inicial.estilo.css:
/* 1. html: a base da página, 112.5% */

/* 2. h1: 2.5rem */

/* 3. h2: 1.25rem */

/* 4. small: 0.75em */

solucao.estilo.css:
html {
  font-size: 112.5%;
}

h1 {
  font-size: 2.5rem;
}

h2 {
  font-size: 1.25rem;
}

small {
  font-size: 0.75em;
}

inicial.estilo.css:
/* 1. body: entrelinha 1.6 (só o número, sem unidade) */

/* 2 e 3. h1: peso 900 e entrelinha 1.1 */

/* 4. blockquote: itálico */

solucao.estilo.css:
body {
  line-height: 1.6;
}

h1 {
  font-weight: 900;
  line-height: 1.1;
}

blockquote {
  font-style: italic;
}

inicial.estilo.css:
/* 1. h1: centralizado (text-align: center) */

/* 2. h1: maiúsculas (text-transform: uppercase) e espaço entre as letras (letter-spacing: 0.3em) */

/* 3. del: riscado em vermelho (text-decoration: line-through red) */

/* 4. a: sem sublinhado (text-decoration: none) e em negrito (font-weight: bold) */

solucao.estilo.css:
h1 {
  text-align: center;
  text-transform: uppercase;
  letter-spacing: 0.3em;
}

del {
  text-decoration: line-through red;
}

a {
  text-decoration: none;
  font-weight: bold;
}

