inicial.estilo.css:
/* 2. html: a base da página */

/* 3. body: a fonte e a entrelinha do texto */

/* 4. h1: família, tamanho, peso, entrelinha e alinhamento */

/* 5. h2: família e tamanho */

/* 6. small: maiúsculas e espaço entre as letras */

/* 7. blockquote: itálico e tamanho */

solucao.estilo.css:
html {
  font-size: 112.5%;
}

body {
  font-family: Verdana, Tahoma, sans-serif;
  line-height: 1.7;
}

h1 {
  font-family: Merriweather, Georgia, serif;
  font-size: 2.25rem;
  font-weight: 900;
  line-height: 1.2;
  text-align: center;
}

h2 {
  font-family: Merriweather, Georgia, serif;
  font-size: 1.5rem;
}

small {
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

blockquote {
  font-style: italic;
  font-size: 1.25em;
}

